import attr
from typing import Optional

from .connection_details import SshServiceDetails
from .pdu import PduPort
from .gnb.du import Cablink
from .gnb.gnb import ClassicalBts
from .enb import DocomoEnb

@attr.s(cmp=False)
class IUG(object):
    """
    Class representing IUG (Intermediate Unit Gateway) object often also called FrontHaul Converter
    which is a DoCoMo specyfic solution for protocol conversion between AirScale ports Nokia CPRI protocol
    and HDBDE and FDD radio DCM CPRI, and ORAN-like TDD

    :param pdu_port PduPort: Information about pdu port for IUG
    :param iug_connection_info SshServiceDetails: SSH parameters for connection to IUG
    :param product_code str: product code of IUG, mandatory parameter
    :param iug_cablink Cablink: IUG cablink configuration, mandatory parameter
    :param serial_number str: serial number of IUG
    """
    pdu_port = attr.ib(default=None, type=Optional[PduPort])
    iug_connection_info = attr.ib(default=None, type=Optional[SshServiceDetails])
    product_code = attr.ib(default=None, type=Optional[str])
    iug_cablink = attr.ib(default=None, type=Optional[list[Cablink]])
    serial_number = attr.ib(default=None, type=Optional[str])


@attr.s(cmp=False)
class MMTVM(object):
    """
    Class representing VM with maintenance and measurement tooling specific for DCM environment

    :param mmtvm_connection_info SshServiceDetails: SSH parameters for connection to MMT VM
    :param dct_interface int: DCT network interface number
    """
    mmtvm_connection_info = attr.ib(default=None, type=Optional[SshServiceDetails])
    dct_interface = attr.ib(default=None, type=Optional[int])

@attr.s(cmp=False)
class DCMMiddleware(object):
    """
    Class which represents Middleware in DoCoMo specific environment

    :param middleware_maintenance_connection SshServiceDetails: SSH parameters for connection to middleware
    :param hostos SshServiceDetails: SSH parameters for connection to HostOS
    :param mmtvm MMTVM: MMTVM class instance object. Represents windows MMT VM connected to Middleware
    :param pdu_port: Information about pdu port for Middleware component
    :param gnbs List[ClassicalBts]: List of gNBs connected to Middleware
    """
    middleware_maintenance_connection = attr.ib(default=None, type=Optional[SshServiceDetails])
    hostos = attr.ib(default=None, type=Optional[SshServiceDetails])
    mmt = attr.ib(default=None, type=Optional[MMTVM])
    pdu_port = attr.ib(default=None, type=Optional[PduPort])
    gnbs = attr.ib(default=None, type=Optional[list[ClassicalBts]])


@attr.s(cmp=False)
class HDBDE(object):
        """
        Class representing HD-BDE (High Density Base station Digital processing Equipment) object.
        This is a component corresponding to the LTE part in the DCM-specific architecture

        :param enb DocomoEnb: DocomoEnb class instance object.
        :param mmt MMTVM: MMTVM class instance object. Represents windows MMT VM connected to HDBDE
        """
        enb = attr.ib(default=None, type=Optional[DocomoEnb])
        mmt = attr.ib(default=None, type=Optional[MMTVM])
